#include <stdio.h>
#include <string.h>

int main(int argc, char **argv) {
    /* Too many arguments: more than 64 strings (excluding program name) */
    if (argc - 1 > 64) {
        puts("TOO_MANY");
        return 0;
    }

    /* No arguments supplied */
    if (argc - 1 == 0) {
        puts("EMPTY");
        return 0;
    }

    /* Any argument longer than 1024 bytes is illegal */
    for (int i = 1; i < argc; ++i) {
        if (strlen(argv[i]) > 1024) {
            puts("TOO_LONG");
            return 0;
        }
    }

    /* Compute longest common prefix */
    const char *first = argv[1];
    size_t prefix_len = strlen(first);

    for (int i = 2; i < argc && prefix_len > 0; ++i) {
        size_t j = 0;
        while (j < prefix_len && first[j] && argv[i][j] && first[j] == argv[i][j]) {
            ++j;
        }
        prefix_len = j; // shrink to common part
    }

    /* Output the prefix (may be empty) followed by a newline */
    if (prefix_len > 0) {
        fwrite(first, 1, prefix_len, stdout);
    }
    putchar('\n');
    return 0;
}
